<?php if (empty($galleries)): ?><p class="empty">暂时还没有图集，等待下一次自动采集。</p><?php else: ?><div class="cards"><?php foreach ($galleries as $item): ?><a class="card" href="<?= h(query_url(['route' => 'gallery', 'slug' => $item['slug']])) ?>" aria-label="打开图集：<?= h($item['title']) ?>"><div class="card-cover"><img loading="lazy" src="<?= h(display_image_url((string) $item['cover_path'], (string) ($item['cover_path'] ?? ''))) ?>" alt="<?= h($item['title']) ?>"><span class="card-index">VIEW SET</span><span class="card-arrow" aria-hidden="true">↗</span></div><div class="card-body"><div class="card-meta"><span class="tag"><?= h($item['category_name']) ?></span><span class="card-action">打开图集</span></div><h3><?= h($item['title']) ?></h3></div></a><?php endforeach; ?></div><?php endif; ?>
